 relation = ''\\n        else:\\n            if current == 't':\\n                subject += ' ' + token\\n            elif current == 's':\\n                object_ += ' ' + token\\n            elif current == 'o':\\n                relation += ' ' + token\\n    if subject != '' and relation != '' and object_ != '' and object_type != '' and subject_type != '':\\n        triplets.append({'head': subject.strip(), 'head_type': subject_type, 'type': relation.strip(),'tail': object_.strip(), 'tail_type': object_type})\\n    return triplets\\nextracted_triplets = extract_triplets_typed(extracted_text[0])\\nprint(extracted_triplets)\\n\\nModel and Tokenizer using transformers\\nfrom transformers import AutoModelForSeq2SeqLM, AutoTokenizer\\n\\ndef extract_triplets_typed(text):\\n    triplets = []\\n    relation = ''\\n    text = text.strip()\\n    current = 'x'\\n    subject, relation, object_, object_type, subject_type = '','','','',''\\n\\n    for token in text.replace(\\\"<s>\\\", \\\"\\\").replace(\\\"<pad>\\\", \\\"\\\").replace(\\\"</s>\\\", \\\"\\\").replace(\\\"tp_XX\\\", \\\"\\\").replace(\\\"__en__\\\", \\\"\\\").split():\\n        if token == \\\"<triplet>\\\" or token == \\\"<relation>\\\":\\n            current = 't'\\n            if relation != '':\\n                triplets.append({'head': subject.strip(), 'head_type': subject_type, 'type': relation.strip(),'tail': object_.strip(), 'tail_type': object_type})\\n                relation = ''\\n           \"\n### Ran Playwright code\n```js\nawait page.evaluate('() => { const main = document.querySelector(\\'main\\'); return main ? main.innerText.substring(0, 5000) : \\'no content\\'; }');\n```"
