() => {
  const prose = document.querySelector('.prose');
  if (!prose) return 'No content found';
  const text = prose.innerText;
  // Search for benchmark, performance, evaluation, accuracy, F1, Chinese, multilingual sections
  const keywords = ['benchmark', 'performance', 'evaluat', 'f1', 'accuracy', 'chinese', 'multilingual', 'language', 'comparison', 'result'];
  const lines = text.split('\n');
  const relevant = [];
  for (let i = 0; i < lines.length; i++) {
    const lower = lines[i].toLowerCase();
    if (keywords.some(k => lower.includes(k))) {
      // Get context around this line
      const start = Math.max(0, i - 2);
      const end = Math.min(lines.length, i + 5);
      relevant.push(lines.slice(start, end).join('\n'));
      relevant.push('---');
    }
  }
  return relevant.length > 0 ? relevant.join('\n') : 'No benchmark/performance info found. Full text length: ' + text.length;
}

